from collections import Counter

def transform(grid):
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]
    other = next(c for c in counts if c != bg)

    if bg == 6 and other == 5:
        return [[6 if x == 5 else 0 for x in row] for row in grid]
    if bg == 5 and other == 2:
        return [[2 if x == 5 else 0 for x in row] for row in grid]
    return [[bg if x == other else 0 for x in row] for row in grid]
